CREATE TABLE source_search_runs(id TEXT PRIMARY KEY REFERENCES missions(id),project_id TEXT NOT NULL REFERENCES projects(id),created_by TEXT NOT NULL REFERENCES user(id),request TEXT NOT NULL CHECK(length(trim(request)) BETWEEN 1 AND 12000),selection_criteria TEXT NOT NULL CHECK(length(trim(selection_criteria)) BETWEEN 1 AND 6000),locale TEXT NOT NULL CHECK(locale IN ('zh-CN','en')),model_id TEXT NOT NULL,reasoning_effort TEXT NOT NULL CHECK(reasoning_effort IN ('low','high','max')),max_steps INTEGER NOT NULL CHECK(max_steps BETWEEN 2 AND 12),search_provider TEXT NOT NULL CHECK(search_provider IN ('catalogs','brave','tavily')),created_at TEXT NOT NULL,UNIQUE(id,project_id));
CREATE INDEX source_search_run_project ON source_search_runs(project_id,created_at);
CREATE TABLE library_records(id TEXT PRIMARY KEY,provider TEXT NOT NULL,external_id TEXT NOT NULL,title TEXT NOT NULL,creators TEXT NOT NULL CHECK(json_valid(creators)),issued_date TEXT NOT NULL DEFAULT '',material_type TEXT NOT NULL DEFAULT '',languages TEXT NOT NULL CHECK(json_valid(languages)),institution TEXT NOT NULL DEFAULT '',collection_name TEXT NOT NULL DEFAULT '',doi TEXT NOT NULL DEFAULT '',handle TEXT NOT NULL DEFAULT '',ark TEXT NOT NULL DEFAULT '',oclc TEXT NOT NULL DEFAULT '',landing_url TEXT NOT NULL,manifest_url TEXT NOT NULL DEFAULT '',download_url TEXT NOT NULL DEFAULT '',rights TEXT NOT NULL DEFAULT '',license TEXT NOT NULL DEFAULT '',access_status TEXT NOT NULL CHECK(access_status IN ('unknown','metadata','restricted','public','open')),metadata TEXT NOT NULL CHECK(json_valid(metadata)),harvested_at TEXT NOT NULL,UNIQUE(provider,external_id));
CREATE INDEX library_record_doi ON library_records(doi) WHERE doi<>'';
CREATE INDEX library_record_landing ON library_records(landing_url);
CREATE VIRTUAL TABLE library_record_fts USING fts5(record_id UNINDEXED,title,creators,institution,collection_name,metadata,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER library_record_search_insert AFTER INSERT ON library_records BEGIN INSERT INTO library_record_fts(record_id,title,creators,institution,collection_name,metadata) VALUES(new.id,new.title,new.creators,new.institution,new.collection_name,new.metadata); END;
CREATE TRIGGER library_record_search_update AFTER UPDATE ON library_records BEGIN DELETE FROM library_record_fts WHERE record_id=old.id; INSERT INTO library_record_fts(record_id,title,creators,institution,collection_name,metadata) VALUES(new.id,new.title,new.creators,new.institution,new.collection_name,new.metadata); END;
CREATE TRIGGER library_record_search_delete AFTER DELETE ON library_records BEGIN DELETE FROM library_record_fts WHERE record_id=old.id; END;
CREATE TABLE source_search_candidates(run_id TEXT NOT NULL,project_id TEXT NOT NULL,record_id TEXT NOT NULL REFERENCES library_records(id),verification_level TEXT NOT NULL CHECK(verification_level IN ('metadata','abstract','finding_aid','ocr_sample','full_text')),decision TEXT NOT NULL CHECK(decision IN ('unreviewed','inspecting','verified','downloadable','needs_file','imported','rejected')),relevance_reason TEXT NOT NULL DEFAULT '',rejection_reason TEXT NOT NULL DEFAULT '',limitations TEXT NOT NULL DEFAULT '',inspected_at TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(run_id,record_id),FOREIGN KEY(run_id,project_id) REFERENCES source_search_runs(id,project_id));
CREATE INDEX source_search_candidate_decision ON source_search_candidates(project_id,decision,updated_at);
CREATE TABLE source_leads(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),record_id TEXT NOT NULL REFERENCES library_records(id),run_id TEXT REFERENCES source_search_runs(id),status TEXT NOT NULL CHECK(status IN ('needs_file','access_restricted','ready','imported','dismissed')),access_note TEXT NOT NULL DEFAULT '',relevance_reason TEXT NOT NULL DEFAULT '',group_id TEXT,resolved_source_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(group_id,project_id) REFERENCES source_groups(id,project_id),FOREIGN KEY(resolved_source_id,project_id) REFERENCES sources(id,project_id),UNIQUE(project_id,record_id));
CREATE INDEX source_lead_project ON source_leads(project_id,status,created_at);
CREATE TABLE library_harvest_state(connector TEXT NOT NULL,collection_id TEXT NOT NULL,cursor TEXT,last_success TEXT,last_error TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,PRIMARY KEY(connector,collection_id));
